from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless, bounded optimizer for serialized character-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        hi = min(len(a), len(b))
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings: List[str]) -> int:
        if len(strings) < 2:
            return 0
        strings = sorted(strings)
        total = 0
        previous = strings[0]
        for current in strings[1:]:
            total += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _stats(values, rows=None):
        counts = {}
        iterator = values if rows is None else (values[r] for r in rows)
        for value in iterator:
            counts[value] = counts.get(value, 0) + 1
        weighted = sum(len(v) * k * (k - 1) for v, k in counts.items())
        pairs = sum(k * (k - 1) for k in counts.values())
        return weighted, pairs

    def _global_order(self, cells, variant):
        n, m = cells.shape
        ranked = []
        for c in range(m):
            weighted, pairs = self._stats(cells[:, c])
            total_length = sum(len(v) for v in cells[:, c])
            if variant == 0:
                key = weighted
            else:
                key = pairs * max(1, total_length // max(1, n))
            ranked.append((key, c))
        return [c for _, c in sorted(ranked, key=lambda x: (-x[0], x[1]))]

    def _tree_orders(self, cells, global_tail):
        n, m = cells.shape
        result = [None] * n
        max_depth = min(4, m)
        candidate_limit = 24

        def finish(rows, prefix, remaining):
            tail = [c for c in global_tail if c in remaining]
            order = prefix + tail
            for r in rows:
                result[r] = order

        def visit(rows, prefix, remaining, depth):
            if len(rows) < 2 or not remaining or depth >= max_depth:
                finish(rows, prefix, remaining)
                return

            # Global-tail ordering limits node work on wide frames, while still
            # allowing the strongest globally useful fields to branch locally.
            choices = [c for c in global_tail if c in remaining][:candidate_limit]
            best_score = 0
            best_col = None
            for c in choices:
                score, _ = self._stats(cells[:, c], rows)
                if score > best_score or (score == best_score and score > 0 and
                                          (best_col is None or c < best_col)):
                    best_score, best_col = score, c

            if best_col is None or best_score <= 0:
                finish(rows, prefix, remaining)
                return

            groups = {}
            for r in rows:
                groups.setdefault(cells[r, best_col], []).append(r)
            # Splitting into singleton-only children creates no future shared prefix.
            if len(groups) == len(rows):
                finish(rows, prefix, remaining)
                return

            next_remaining = [c for c in remaining if c != best_col]
            for child in groups.values():
                visit(child, prefix + [best_col], next_remaining, depth + 1)

        visit(list(range(n)), [], list(range(m)), 0)
        return result

    @staticmethod
    def _strings(cells, orders):
        return ["".join(cells[r, c] for c in orders[r])
                for r in range(cells.shape[0])]

    def _candidate(self, cells, orders):
        strings = self._strings(cells, orders)
        score = self._score(strings)
        rows = sorted(range(len(strings)), key=lambda r: (strings[r], r))
        return score, rows

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        n, m = df.shape
        self.num_rows, self.num_cols = n, m
        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)
        for r in range(n):
            for c in range(m):
                cells[r, c] = self._cell_text(raw[r, c])

        # Unknown caller-specific ordering constraints are safest under identity:
        # identity cannot violate an already valid source arrangement.
        constrained = bool(col_merge) or bool(one_way_dep)
        identity = list(range(m))
        if constrained:
            orders = [identity[:] for _ in range(n)]
            _, row_order = self._candidate(cells, orders)
            out = raw[row_order, :]
            result = pd.DataFrame(out, columns=df.columns, index=df.index.take(row_order))
            return result, [[df.columns[c] for c in identity] for _ in range(n)]

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        tree = self._tree_orders(cells, global_a)

        candidates = (
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            tree,
        )
        best = None
        for orders in candidates:
            score, row_order = self._candidate(cells, orders)
            signature = tuple(-c for c in orders[0])
            choice = (score, signature)
            if best is None or choice > best[0]:
                best = (choice, row_order, orders)

        _, row_order, orders = best
        out = np.empty((n, m), dtype=object)
        column_orders = []
        for dst, src in enumerate(row_order):
            order = orders[src]
            out[dst, :] = [raw[src, c] for c in order]
            column_orders.append([df.columns[c] for c in order])

        result = pd.DataFrame(out, columns=df.columns, index=df.index.take(row_order))
        return result, column_orders
